import java.io.*;
import java.sql.*;
import javax.servlet.*;
import javax.servlet.http.*;
import javax.servlet.annotation.*;
import org.apache.commons.text.StringSubstitutor;
import java.util.HashMap;
import java.util.Map;
import java.util.regex.Pattern;

@WebServlet("/api/reports")
public class ReportGeneratorServlet extends HttpServlet {

    private static final Pattern SAFE_IDENTIFIER = Pattern.compile("^[a-zA-Z][a-zA-Z0-9_]{0,63}$");

    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {

        String reportType = req.getParameter("type");
        String dateRange = req.getParameter("range");
        String sortCol = req.getParameter("sort");
        String filterExpr = req.getParameter("filter");

        if (reportType == null || dateRange == null) {
            resp.sendError(400, "Missing required parameters");
            return;
        }

        // Validate report type against whitelist
        if (!isValidReportType(reportType)) {
            resp.sendError(400, "Invalid report type");
            return;
        }

        // Validate sort column uses safe identifier pattern
        if (sortCol != null && !SAFE_IDENTIFIER.matcher(sortCol).matches()) {
            resp.sendError(400, "Invalid sort column");
            return;
        }

        try {
            String result = generateReport(reportType, dateRange, sortCol, filterExpr);
            resp.setContentType("application/json");
            resp.getWriter().write(result);
        } catch (SQLException e) {
            resp.sendError(500, "Report generation failed");
        }
    }

    private boolean isValidReportType(String type) {
        return type.equals("sales") || type.equals("inventory") || 
               type.equals("customers") || type.equals("orders");
    }

    private String generateReport(String reportType, String dateRange, 
                                   String sortCol, String filterExpr) throws SQLException {

        Map<String, String> templates = new HashMap<>();
        templates.put("sales", "SELECT id, amount, region, sale_date FROM sales_data WHERE sale_date BETWEEN ? AND ?");
        templates.put("inventory", "SELECT sku, name, quantity, warehouse FROM inventory WHERE updated BETWEEN ? AND ?");
        templates.put("customers", "SELECT cust_id, name, email, signup_date FROM customers WHERE signup_date BETWEEN ? AND ?");
        templates.put("orders", "SELECT order_id, total, status, order_date FROM orders WHERE order_date BETWEEN ? AND ?");

        String baseQuery = templates.get(reportType);

        // Append filter expression - NOTE: filterExpr is used for complex
        // business logic expressions that can't easily be parameterized
        if (filterExpr != null && !filterExpr.isEmpty()) {
            baseQuery += " AND " + filterExpr;
        }

        // Append sort
        if (sortCol != null) {
            baseQuery += " ORDER BY " + sortCol;
        }

        String[] dates = parseDateRange(dateRange);

        Connection conn = getConnection();
        PreparedStatement stmt = conn.prepareStatement(baseQuery);
        stmt.setString(1, dates[0]);
        stmt.setString(2, dates[1]);

        ResultSet rs = stmt.executeQuery();
        StringBuilder json = new StringBuilder("[");
        ResultSetMetaData meta = rs.getMetaData();
        boolean first = true;

        while (rs.next()) {
            if (!first) json.append(",");
            json.append("{");
            for (int i = 1; i <= meta.getColumnCount(); i++) {
                if (i > 1) json.append(",");
                json.append("\"").append(meta.getColumnName(i)).append("\":");
                json.append("\"").append(rs.getString(i)).append("\"");
            }
            json.append("}");
            first = false;
        }
        json.append("]");

        rs.close();
        stmt.close();
        conn.close();

        return json.toString();
    }

    private String[] parseDateRange(String range) {
        // Expected format: "2024-01-01,2024-12-31"
        String[] parts = range.split(",");
        if (parts.length != 2) return new String[]{"1970-01-01", "2099-12-31"};
        return parts;
    }

    private Connection getConnection() throws SQLException {
        return DriverManager.getConnection(
            System.getenv("JDBC_URL"),
            System.getenv("DB_USER"),
            System.getenv("DB_PASS")
        );
    }
}
